def transform(grid):
    # Convex hull of the non-zero pixels
    rows = [r for r, row in enumerate(grid) if any(v != 0 for v in row)]
    cols = [c for c in range(len(grid[0])) if any(grid[r][c] != 0 for r in range(len(grid)))]
    r_min, r_max = min(rows), max(rows)
    c_min, c_max = min(cols), max(cols)
    val = grid[r_min][c_min]
    out = [row[:] for row in grid]
    # Bounding box perimeter except keep interior intact
    for r in (r_min, r_max):
        for c in range(c_min, c_max + 1):
            out[r][c] = val
    for c in (c_min, c_max):
        for r in range(r_min, r_max + 1):
            out[r][c] = val
    return out
